import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj1 = [[] for _ in range(n+1)]
    adj2 = [[] for _ in range(n+1)]
    edges1 = []
    edges2 = []

    for _ in range(n-1):
        a, b = map(int, sys.stdin.readline().split())
        adj1[a].append(b)
        adj1[b].append(a)
        edges1.append((a, b))

    for _ in range(n-1):
        c, d = map(int, sys.stdin.readline().split())
        adj2[c].append(d)
        adj2[d].append(c)
        edges2.append((c, d))

    parent1 = [0]*(n+1)
    parent2 = [0]*(n+1)
    depth1 = [0]*(n+1)
    depth2 = [0]*(n+1)

    def bfs(root, adj, parent, depth):
        q = deque([root])
        parent[root] = 0
        depth[root] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if parent[u] != v:
                    parent[v] = u
                    depth[v] = depth[u] + 1
                    q.append(v)

    bfs(1, adj1, parent1, depth1)
    bfs(1, adj2, parent2, depth2)

    lca1 = [[0]*(n+1) for _ in range(20)]
    lca2 = [[0]*(n+1) for _ in range(20)]

    for v in range(1, n+1):
        lca1[0][v] = parent1[v]
    for v in range(1, n+1):
        lca2[0][v] = parent2[v]

    for k in range(1, 20):
        for v in range(1, n+1):
            lca1[k][v] = lca1[k-1][lca1[k-1][v]]
            lca2[k][v] = lca2[k-1][lca2[k-1][v]]

    def get_lca(u, v, lca):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(19, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = lca[k][u]
        if u == v:
            return u
        for k in range(19, -1, -1):
            if lca[k][u] != lca[k][v]:
                u = lca[k][u]
                v = lca[k][v]
        return parent[u]

    def is_valid(e1, e2):
        a, b = e1
        c, d = e2
        lca_a_b = get_lca(a, b, lca1)
        lca_c_d = get_lca(c, d, lca2)
        if lca_a_b == a and lca_a_b == b:
            return False
        if lca_c_d == c and lca_c_d == d:
            return False
        lca_a_c = get_lca(a, c, lca1)
        lca_a_d = get_lca(a, d, lca1)
        lca_b_c = get_lca(b, c, lca1)
        lca_b_d = get_lca(b, d, lca1)
        if (lca_a_c == a and lca_a_d == a) or (lca_b_c == b and lca_b_d == b):
            return False
        if (lca_a_c == c and lca_a_d == d) or (lca_b_c == c and lca_b_d == d):
            return False
        return True

    m = 0
    matched1 = [False] * (n-1)
    matched2 = [False] * (n-1)
    res = []

    for i in range(n-1):
        if matched1[i]:
            continue
        a, b = edges1[i]
        for j in range(n-1):
            if matched2[j]:
                continue
            c, d = edges2[j]
            if is_valid((a, b), (c, d)):
                matched1[i] = True
                matched2[j] = True
                res.append((a, b, c, d))
                m += 1
                break

    print(m)
    for a, b, c, d in res:
        print(a, b, c, d)

if __name__ == '__main__':
    main()
